css:
.root {
  --theme-tint: 0.35;
  --theme-blur: 18px;
  --theme-saturate: 200%;
  --theme-bg: rgb(255 255 255 / calc(0.5 + 0.5 * var(--theme-tint)));
  --theme-bg-thick: rgb(255 255 255 / calc(0.62 + 0.38 * var(--theme-tint)));
  --theme-fill: rgb(255 255 255 / 0.6);
  --theme-sheen: linear-gradient(160deg, rgb(255 255 255 / 0.55) 0%, rgb(255 255 255 / 0.12) 38%, rgb(255 255 255 / 0) 60%);
  --theme-highlight: rgb(255 255 255 / 0.95);
  --theme-rim: rgb(255 255 255 / 0.5);
  --theme-edge: rgb(0 0 0 / 0.08);
  --theme-shadow: 0 2px 6px rgb(16 24 40 / 0.06), 0 24px 60px -18px rgb(16 24 40 / 0.32);
  --theme-dimmed: rgb(60 60 67 / 0.82);
}
.dark {
  --theme-bg: rgb(34 34 40 / calc(0.45 + 0.55 * var(--theme-tint)));
  --theme-bg-thick: rgb(34 34 40 / calc(0.6 + 0.4 * var(--theme-tint)));
  --theme-fill: rgb(255 255 255 / 0.08);
  --theme-sheen: linear-gradient(160deg, rgb(255 255 255 / 0.14) 0%, rgb(255 255 255 / 0.03) 40%, rgb(255 255 255 / 0) 60%);
  --theme-highlight: rgb(255 255 255 / 0.22);
  --theme-rim: rgb(255 255 255 / 0.08);
  --theme-edge: rgb(0 0 0 / 0.6);
  --theme-shadow: 0 2px 6px rgb(0 0 0 / 0.4), 0 28px 64px -16px rgb(0 0 0 / 0.85);
  --theme-dimmed: rgb(235 235 245 / 0.64);
}
.dialog, .popover, .tabs, .notification, .nav, .phone-bar {
  --dimmed: var(--theme-dimmed);
  background: var(--theme-sheen), var(--theme-bg);
  -webkit-backdrop-filter: blur(var(--theme-blur)) saturate(var(--theme-saturate));
  backdrop-filter: blur(var(--theme-blur)) saturate(var(--theme-saturate));
  border: 0;
  box-shadow: inset 0 1px 0 var(--theme-highlight), inset 0 0 0 1px var(--theme-rim), inset 0 -1px 0 rgb(0 0 0 / 0.06), 0 0 0 0.5px var(--theme-edge), var(--theme-shadow);
}
.dialog, .nav {
  --theme-blur: 24px;
  background: var(--theme-sheen), var(--theme-bg-thick);
}
.overlay { background: rgb(0 0 0 / 0.25); }
.tabs { width: fit-content; max-width: 100%; padding: 4px; border-radius: calc(var(--radius) + 4px); }
.tabs::before { display: none; }
.tab { border: 0; border-radius: var(--radius); margin: 0; }
.tab[data-active] { background: var(--accent); color: var(--accent-contrast); box-shadow: 0 4px 12px -4px color-mix(in srgb, var(--accent) 70%, transparent); }
.screen-head .icon-button[data-variant=default], .screen-head .button[data-variant=default] {
  background: var(--theme-fill);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  backdrop-filter: blur(12px) saturate(180%);
  border-color: var(--theme-edge);
  box-shadow: inset 0 1px 0 var(--theme-highlight), 0 6px 16px -8px rgb(0 0 0 / 0.3);
}
.chat-phone .dialog { background: var(--body); -webkit-backdrop-filter: none; backdrop-filter: none; }
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .root { --theme-tint: 1; }
}
@media (prefers-reduced-transparency: reduce) {
  .root { --theme-tint: 1; --theme-sheen: linear-gradient(transparent, transparent); }
  .dialog, .popover, .tabs, .notification, .nav, .phone-bar { -webkit-backdrop-filter: none; backdrop-filter: none; }
}
@media (prefers-contrast: more) {
  .root { --theme-tint: 1; --theme-sheen: linear-gradient(transparent, transparent); }
  .dialog, .popover, .tabs, .notification, .nav, .phone-bar { --dimmed: var(--text); -webkit-backdrop-filter: none; backdrop-filter: none; box-shadow: 0 0 0 1px var(--text); }
}
@media (forced-colors: active) {
  .dialog, .popover, .tabs, .notification, .nav, .phone-bar { -webkit-backdrop-filter: none; backdrop-filter: none; }
}
